(async()=>{const t=await(await fetch('http://127.0.0.1:9222/json/list')).json(),p=t.find(x=>x.type==='page'&&x.url.includes('127.0.0.1:8000'));const w=new WebSocket(p.webSocketDebuggerUrl);await new Promise(r=>w.onopen=r);let id=0,pending=new Map();w.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};function c(method,params={}){return new Promise(r=>{const n=++id;pending.set(n,r);w.send(JSON.stringify({id:n,method,params}))})}async function ev(expression){const r=await c('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.result.exceptionDetails)throw Error(r.result.exceptionDetails.text);return r.result.result.value}await c('Page.enable');await c('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});const pre=await ev("({overlay:!document.querySelector('#overlay').classList.contains('hidden'),title:document.querySelector('#resultTitle').textContent})");await ev("document.querySelector('#againBtn').click()");const replay=await ev("({overlayHidden:document.querySelector('#overlay').classList.contains('hidden'),menuHidden:document.querySelector('#menu').classList.contains('hidden'),hp:document.querySelector('#healthText').textContent,kills:document.querySelector('#kills').textContent,alive:document.querySelector('#aliveHud').textContent,storm:document.querySelector('#stormTimer').textContent})");const shot=await c('Page.captureScreenshot',{format:'jpeg',quality:80,fromSurface:true});fs.writeFileSync('/tmp/arcana-latest.jpg',Buffer.from(shot.result.data,'base64'));console.log(JSON.stringify({pre,replay},null,2));w.close()})().catch(e=>{console.error(e);process.exit(1)});
EOF
